fn frame(t: i32) {
    host::display::clear(0x000000);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let r: i32 = 90;
    let done: i32 = (t / 2) % 256;
    let mut a: i32 = 0;
    while a < 256 {
        let col: i32 = if a < done { 0x33ddff } else { 0x1a2a30 };
        let x: i32 = cx + (r * host::math::cos(a - 64)) / 256;
        let y: i32 = cy + (r * host::math::sin(a - 64)) / 256;
        host::display::fill_rect(x - 2, y - 2, 5, 5, col);
        a = a + 3;
    }
    let pct: i32 = (done * 100) / 256;
    host::display::draw_number(cx - 20, cy - 8, pct, 0xffffff, 3);
    host::display::present();
}
